g.script:
(function(){
  var TOP=111, VH=913, y=0, user=false, raf=0, cur=0;
  var svg=document.documentElement, page=document.getElementById("page"), thumb=document.getElementById("thumb"),
      vp=document.getElementById("viewport"), hint=document.getElementById("hint"), st=document.querySelectorAll(".st"), hot=document.querySelectorAll(".hot");
  function PH(){ return +st[cur].getAttribute("data-h"); }
  function MAX(){ return Math.max(0,PH()-VH); }
  function TH(){ return Math.max(60,(VH-8)*VH/PH()); }
  function set(v){ var m=MAX(); y=Math.max(0,Math.min(m,v)); page.setAttribute("transform","translate(0 "+(TOP-y)+")");
    thumb.setAttribute("height",TH()); thumb.setAttribute("opacity",m>0?1:0); thumb.setAttribute("y",TOP+4+(VH-8-TH())*(m?y/m:0)); }
  function show(i){ cur=i; for(var k=0;k<st.length;k++) st[k].setAttribute("opacity",k===i?1:0); set(y); }
  function scale(){ var m=svg.getScreenCTM(); return m?m.a:1; }
  function takeover(){ if(!user){ user=true; cancelAnimationFrame(raf); clearTimeout(tt); hint.setAttribute("opacity","0"); } }
  for(var k=0;k<hot.length;k++){ (function(h){ h.addEventListener("click",function(e){ takeover(); show(+h.getAttribute("data-i")); e.stopPropagation(); });
     h.addEventListener("pointerdown",function(e){ e.stopPropagation(); }); })(hot[k]); }
  svg.addEventListener("wheel",function(e){
    var d=e.deltaY*(e.deltaMode===1?32:e.deltaMode===2?VH:1)/scale();
    if((d<0&&y<=0)||(d>0&&y>=MAX())) return;
    e.preventDefault(); takeover(); set(y+d);
  },{passive:false});
  var drag=null;
  vp.addEventListener("pointerdown",function(e){ takeover(); drag={sy:e.clientY,y0:y,onThumb:e.target===thumb}; vp.style.cursor="grabbing"; try{vp.setPointerCapture(e.pointerId);}catch(_){} });
  vp.addEventListener("pointermove",function(e){ if(!drag) return; var d=(e.clientY-drag.sy)/scale();
    set(drag.onThumb? drag.y0+d*MAX()/(VH-8-TH()) : drag.y0-d); });
  function end(){ drag=null; vp.style.cursor="grab"; }
  vp.addEventListener("pointerup",end); vp.addEventListener("pointercancel",end); vp.style.touchAction="none";
  svg.addEventListener("keydown",function(e){ var k={ArrowDown:60,ArrowUp:-60,PageDown:VH*.9,PageUp:-VH*.9," ":VH*.9,Home:-1e5,End:1e5}[e.key];
    if(k){ e.preventDefault(); takeover(); set(y+k); } });
  function ease(t){ return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2; }
  function tween(a,b,ms,next){ var t0=performance.now(); (function step(now){ if(user) return;
      var t=Math.min(1,(now-t0)/ms); set(a+(b-a)*ease(t)); if(t<1) raf=requestAnimationFrame(step); else if(next) tt=setTimeout(next,1200); })(t0); }
  var started=false, tt=0;
  function demo(){ if(started||user) return; started=true; hint.setAttribute("opacity","1");
    if(st.length>1){ var i=0; var cyc=function(){ if(user) return; i=(i+1)%st.length; show(i); tt=setTimeout(cyc,2600); }; tt=setTimeout(cyc,2200); return; }
    tt=setTimeout(function(){ var m=MAX(), dn=Math.max(2500,m*4.5); tween(0,m,dn,function(){ tween(m,0,dn*.55,function(){ hint.setAttribute("opacity","0"); }); }); },900); }
  try{ new IntersectionObserver(function(es){ if(es[0].isIntersecting&&es[0].intersectionRatio>.5) demo(); },{threshold:[.5]}).observe(svg); }
  catch(_){ setTimeout(demo,600); }
  show(0);
})();
